insert into public.portfolio_items (slug, title, city, area, client, description, services, cover_url, gallery, published, position) values
  ('bremen-boconcept', 'BoConcept', 'Bremen', '576 m²', 'Immobilienfonds', 'Schlüsselfertiger Ausbau eines neuen BoConcept Stores als Generalübernehmer. Eröffnung nach nur 3,5 Monaten Bauzeit.', array['Generalübernehmerschaft bis zur Übergabe', 'Integrierte Planung von Architektur, Innenausbau und TGA', 'Wiederverwendung vorhandener Materialien', 'Treppenschließung über zwei Etagen', 'Maßmöbel nach BoConcept-Designrichtlinien']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2025-10/boconcept3.png.webp?itok=_5N1va4H', array['https://qvinterio.de/sites/qvinterio/files/2025-10/boconcept2.png', 'https://qvinterio.de/sites/qvinterio/files/2025-10/boconcept.png']::text[], true, 0),
  ('frankfurt-el50', 'EL50', 'Frankfurt am Main', '555 m²', 'Immobilienfonds', 'Hochwertiger Mieterausbau für eine bundesweit tätige Anwaltskanzlei, vom Mietvertrag bis zur Übergabe in 3 Monaten. Die Bestandsglaswände wurden zu 100 % wiederverwendet.', array['Generalübernehmer-Ausbau bis zur schlüsselfertigen Übergabe', 'Architektur- und TGA-Planung', 'Wiederverwendung der Bestandsglaswände', 'Maßmöbel: Spindschrank, Küchenzeile']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2025-02/20240930_073128198_ios_2.jpeg.webp?h=8b7a8168&itok=1OU2nrWt', array['https://qvinterio.de/sites/qvinterio/files/2025-02/20240930_074706316_ios.jpeg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/20240930_073418715_ios.jpeg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/20241015_115009810_ios.jpeg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/20241015_115045744_ios.jpeg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/20241015_115302147_ios.jpeg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/20241015_115337570_ios.jpeg']::text[], true, 1),
  ('hamburg-goldbekhoefe', 'Goldbekhöfe', 'Hamburg', '1.200 m²', 'Immobilienfonds', 'Mieterausbau einer hochwertigen Bürofläche in Hamburg-Winterhude bei laufendem Objektbetrieb, termingerecht übergeben.', array['Komplette Neugestaltung der Bürofläche', 'Begleitung von der Planung bis zur Fertigstellung']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2025-02/20230926_074001449_iOS%20conv.jpg.webp?h=1ac6ba76&itok=l1JmHge-', array['https://qvinterio.de/sites/qvinterio/files/2025-02/20230926_081258483_ios_conv.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/20230926_082347750_ios_conv.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/20230926_082646974_ios_conv.jpg']::text[], true, 2),
  ('hamburg-stadtkueken', 'Stadtküken', 'Hamburg', '300 m²', 'Immobilienfonds', 'Kompletter Mieterausbau einer Büro- und Verwaltungsfläche in den Goldbekhöfen, vom Rückbau bis zu modernen Arbeitsbereichen.', array['Rückbau der Bestandsflächen', 'Neue Raumstrukturen in Trockenbauweise', 'Koordination aller Ausbaugewerke']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2026-05/chatgpt_image_6._mai_2026_12_04_35_2.png.webp?itok=78D8z_Yg', array['https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_6._mai_2026_12_04_35_1.png.webp?itok=WuwBnFCK', 'https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_6._mai_2026_12_04_38_4.png.webp?itok=fyW67wVE', 'https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_6._mai_2026_12_04_38_3.png.webp?itok=omGMko_U']::text[], true, 3),
  ('leipzig-fs-ecommerce', 'FS eCommerce', 'Leipzig', '500 m²', 'FS eCommerce', 'Neuaufteilung des 3. Obergeschosses für neue Anforderungen, bei gleicher Fläche und Nutzung.', array['Ganzheitliche Gestaltung des Geschosses', 'Koordination und Ausführung aller Leistungen bis zur Übergabe']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2025-01/leipzig-img_3988.jpg.webp?h=d528f0f5&itok=dCKSBayW', array['https://qvinterio.de/sites/qvinterio/files/2025-01/leipzig-img_3998.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-01/leipzig-img_3991.jpg']::text[], true, 4),
  ('hamburg-winterhude', 'Winterhude', 'Hamburg', '800 m²', 'Immobilienfonds', 'Anspruchsvoller Mieterausbau, termingerecht und auf hohem Qualitätsniveau von der Planung bis zur Fertigstellung.', array['Innenausbau: Decken, Böden, Wände', 'Wände mit erhöhtem Schallschutz', 'Sanitär, Elektro- und Kommunikationstechnik', 'Klima- und Lüftungstechnik', 'Brandschutzmaßnahmen']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2025-02/whatsapp_bild_2024-09-12_um_12.44.26_98240802.jpg.webp?itok=9sWtl6Kt', array['https://qvinterio.de/sites/qvinterio/files/2025-02/whatsapp_bild_2024-09-12_um_12.44.26_3f1318ba.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/whatsapp_bild_2024-09-12_um_12.44.27_0f1af532.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/whatsapp_bild_2024-09-12_um_12.44.27_04f7ad45.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/whatsapp_bild_2024-09-12_um_12.44.27_381fdb6b.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/whatsapp_bild_2024-09-12_um_12.44.27_aff982d1.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/whatsapp_bild_2024-09-12_um_12.44.27_e29d60ff.jpg']::text[], true, 5),
  ('essen-lindenallee', 'Lindenallee', 'Essen', '2.400 m²', 'Immobilienfonds', 'Hochwertiger Mieterausbau mit neu geplanter Raumstruktur, umfangreichem Rückbau und offenen Arbeitsbereichen.', array['Entwurf und Planung der Raumstruktur', 'Rückbau großer Teile der Bestandsfläche', 'Umlaufender Flur und Open-Space-Flächen', 'Klimatisierte Besprechungscubes aus Eigenproduktion']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2025-02/20240508_093641546_ios.jpg.webp?itok=Jnjprd0q', array['https://qvinterio.de/sites/qvinterio/files/2025-02/20240508_093647449_ios.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/20240508_100833786_ios.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/img_0582_r1.jpg']::text[], true, 6),
  ('radiologie-nuernberg', 'Radiologie', 'Nürnberg', '380 m²', 'Immobilienfonds', 'Umbau einer Radiologie-Praxis bei laufendem Betrieb, inklusive Einbindung medizinischer Großgeräte.', array['Generalunternehmung', 'Abbruch und Ausbau der Praxisflächen', 'Einbindung medizinischer Großgeräte', 'Empfang, Wartebereich, CT-Raum und Flur']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2026-05/chatgpt_image_7._mai_2026_12_20_00.png.webp?itok=KfwQy6V0', array['https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_7._mai_2026_12_15_42.png.webp?itok=ZKEiUWPD', 'https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_7._mai_2026_12_15_34.png.webp?itok=ey5DRF8x', 'https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_7._mai_2026_12_26_28.png.webp?itok=ucdb9GlU', 'https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_7._mai_2026_12_15_28.png.webp?itok=hgPg47R1']::text[], true, 7),
  ('hamburg-glueckkanja', 'GlueckKanja', 'Hamburg', '370 m²', 'Immobilienfonds', 'Mieterausbau einer Bürofläche in den Goldbekhöfen mit offenen Arbeits- und Kommunikationsbereichen.', array['Rückbau, Abbruch und Trockenbau', 'Boden-, Decken- und Malerarbeiten', 'Elektro-, Klima- und Lüftungstechnik']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2026-05/chatgpt_image_6._mai_2026_12_48_20_2.png.webp?itok=K_uUDiav', array['https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_6._mai_2026_12_48_19_1.png.webp?itok=_uNXKu9J', 'https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_6._mai_2026_12_48_20_3.png.webp?itok=wWsiBs7y']::text[], true, 8),
  ('pullach-sixt', 'SIXT', 'Pullach', '200 m²', 'Sixt', 'Anspruchsvoller Mieterausbau, begleitet von der Planung bis zur Fertigstellung.', array['Planung bis Fertigstellung']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2025-02/_ra_5233.jpg.webp?itok=zkfM9yp0', array['https://qvinterio.de/sites/qvinterio/files/2025-02/_ra_5184.jpg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/_ra_5216.jpg']::text[], true, 9),
  ('hamburg-beomed', 'Beomed', 'Hamburg', '350 m²', 'Immobilienfonds', 'Ausbau einer Bürofläche als Generalunternehmer, vom Abbruch bis zur bezugsfertigen Übergabe.', array['Abbruch', 'Oberflächen und Teppichboden', 'Beleuchtung', 'Teeküche und Sanitärbereich']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2026-05/chatgpt_image_7._mai_2026_09_52_10_3.png.webp?itok=cscrd_1N', array['https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_7._mai_2026_09_52_10_1.png.webp?itok=VDtjhV3Q', 'https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_7._mai_2026_09_52_10_2.png.webp?itok=wgS7oklt', 'https://qvinterio.de/sites/qvinterio/files/styles/1000_1000/public/2026-05/chatgpt_image_7._mai_2026_09_52_10_4.png.webp?itok=yWT5GLMa']::text[], true, 10),
  ('hamburg-moorfurthweg', 'Moorfurthweg', 'Hamburg', '880 m²', 'Immobilienfonds', 'Hochwertiger Mieterausbau einer Anwaltskanzlei, termingerecht und bei laufendem Betrieb.', array['Empfangstheke mit Raumtrenner', 'Glassystemwände', 'Bodenbeläge', 'Teeküche', 'Sanitärzellen']::text[], 'https://qvinterio.de/sites/qvinterio/files/styles/900_900/public/2025-02/20230725_081533882_ios.jpeg.webp?itok=ngAr6-xK', array['https://qvinterio.de/sites/qvinterio/files/2025-02/20230725_081449387_ios.jpeg', 'https://qvinterio.de/sites/qvinterio/files/2025-02/20230725_081542302_ios.jpeg']::text[], true, 11)
insert into public.services (position, title_de, text_de, title_uk, text_uk, icon_url) values
  (0, 'Glassystemwände', 'Individuell gefertigte, flexible Glaswände mit kurzen Lieferzeiten.', 'Скляні системні стіни', 'Скляні перегородки на замовлення з коротким терміном поставки.', '/leistungen/01-glassystemwaende.webp'),
  (1, 'Bestandsglaswände', 'Fachgerechte Demontage und Wiedereinbau bestehender Glassysteme.', 'Наявні скляні стіни', 'Демонтаж і повторний монтаж наявних скляних систем.', '/leistungen/02-bestandsglaswaende.webp'),
  (2, 'Individuelle Möbel', 'Empfangstheken, Schränke, Garderoben und Waschtischunterschränke nach Maß.', 'Меблі на замовлення', 'Стійки рецепції, шафи, гардероби і тумби під умивальники.', '/leistungen/03-individuelle-moebel.webp'),
  (3, 'Teeküchen', 'Maßgefertigte Teeküchen inklusive Lieferung und Montage.', 'Кухні для персоналу', 'Кухні на замовлення з доставкою і монтажем.', '/leistungen/04-teekuechen.webp'),
  (4, 'Brandschutzsanierung', 'Sanierung nach höchsten Sicherheitsstandards.', 'Протипожежна санація', 'Санація за найвищими стандартами безпеки.', '/leistungen/05-brandschutzsanierung.webp'),
  (5, 'Türen', 'Brandschutz-, Rohrrahmen-, Zugangs-, Holz- und Glastüren.', 'Двері', 'Протипожежні, рамні, вхідні, дерев''яні та скляні двері.', '/leistungen/06-tueren.webp'),
  (6, 'Kälte- und Lüftungsinstallation', 'Effiziente Klimatisierung für gesunde Raumluft.', 'Кондиціювання і вентиляція', 'Ефективний клімат для здорового повітря.', '/leistungen/07-kaelte-lueftung.webp'),
  (7, 'Abbruch und Rückbau', 'Von der Entkernung bis zum Abriss, inklusive Schadstoffentsorgung.', 'Демонтаж', 'Від розбирання до знесення, з утилізацією шкідливих матеріалів.', '/leistungen/08-abbruch-rueckbau.webp'),
  (8, 'Trockenbau', 'Schnelle, kostengünstige Raumlösungen.', 'Гіпсокартон', 'Швидкі й недорогі рішення для планування.', '/leistungen/09-trockenbau.webp'),
  (9, 'Maler- und Lackierarbeiten', 'Hochwertige Wandgestaltung mit moderner Technik.', 'Малярні роботи', 'Якісне оформлення стін сучасними матеріалами.', '/leistungen/10-maler-lackierarbeiten.webp'),
  (10, 'Deckensysteme', 'Abgehängte, Akustik- und OWA-Decken.', 'Стельові системи', 'Підвісні, акустичні та OWA-стелі.', '/leistungen/11-deckensysteme.webp'),
  (11, 'Fliesenarbeiten', 'Böden und Wände in modernem oder klassischem Design.', 'Плитка', 'Підлоги і стіни в сучасному чи класичному дизайні.', '/leistungen/12-fliesenarbeiten.webp'),
  (12, 'Baureinigung', 'Gründliche Reinigung nach Bauabschluss.', 'Прибирання після будівництва', 'Ретельне прибирання після завершення робіт.', '/leistungen/13-baureinigung.webp'),
  (13, 'Elektro- und Kommunikationstechnik', 'Elektro- und Netzwerklösungen für reibungslose Abläufe.', 'Електрика і зв''язок', 'Електрика і мережі для безперебійної роботи.', '/leistungen/14-elektro-kommunikation.webp'),
  (14, 'Heizung und Sanitär', 'Sanitärinstallationen nach Maß, Heizkörper und Abwasser.', 'Опалення і сантехніка', 'Сантехніка на замовлення, радіатори і каналізація.', '/leistungen/15-heizung-sanitaer.webp'),
  (15, 'Bodenbeläge', 'Teppich-, Industrie- und Vinylböden für gewerbliche Nutzung.', 'Підлогові покриття', 'Килимові, промислові та вінілові підлоги для комерційних приміщень.', '/leistungen/16-bodenbelaege.webp');
